class Nada:
    "One shared model with a state the UI can poll: idle, starting, ready or failed"

    def __init__(self):
        self.state, self.device, self.error, self.eng = "idle", None, None, None
        self.lock, self.pool = threading.Lock(), ThreadPoolExecutor(1)

    def warm_up(self):
        with self.lock:
            if self.state in ("starting", "ready"):
                return
            self.state, self.error = "starting", None
        self.pool.submit(self._load)

    def _load(self):
        try:
            self.eng = Engine()
            self.device, self.state = self.eng.device, "ready"
        except Exception as e:
            traceback.print_exc()
            self.error, self.state = f"{type(e).__name__}: {e}", "failed"

    def _embed(self, x):
        if not self.eng:
            raise RuntimeError(f"nada could not start. {self.error or ''}")
        return self.eng.embed(x)

    async def embed(self, x):
        "Embed only when the model is already loaded — never auto-starts wav2vec."
        if self.state == "idle":
            raise RuntimeError("Sound model is off. Number→glyph typing does not need it. Run `pixi run install` and call warm_up to enable mic recognition.")
        if self.state == "starting":
            raise RuntimeError("Sound model is still loading.")
        if self.state == "failed":
            raise RuntimeError(f"Sound model failed to load. {self.error or ''}")
        return await asyncio.get_running_loop().run_in_executor(self.pool, self._embed, x)


